const now = Date.now();
$workflow.staticData.currentRequestStart = now;
const { requestId, operation, path } = $json;
if (!requestId || !operation || !path) {
  return { json: { ...$json, error: { code: 'VALIDATION_ERROR', message: 'Missing required fields' } } };
}
return { json: { ...$json } };

const { path, operation } = $json;
if (path && (path.includes('..') || path.includes('/') || path.includes('\\'))) {
  return { json: { ...$json, error: { code: 'PATH_SECURITY_ERROR', message: 'Path traversal detected' } } };
}
if (operation === 'delete' && !$json.confirmationToken) {
  return { json: { ...$json, error: { code: 'CONFIRMATION_REQUIRED', message: 'Delete requires confirmation' } } };
}
return { json: { ...$json } };

const op = $json.operation;
const requestId = $json.requestId;
if (op === 'read') {
  const infoResult = $json._fileSize;
  if (infoResult && infoResult > 10 * 1024 * 1024) {
    return { json: { success: false, tool: 'file-manager', requestId, durationMs: Date.now() - ($workflow.staticData.currentRequestStart || Date.now()), result: null, error: { code: 'FILE_SIZE_LIMIT', message: 'File exceeds 10MB read limit', retryable: false } }, httpStatusCode: 413 };
  }
}
const result = $json.data || $json.result || null;
return { json: { success: !($json.error), tool: 'file-manager', requestId, durationMs: Date.now() - ($workflow.staticData.currentRequestStart || Date.now()), result, error: $json.error || null, operation: $json.operation || null } };

const out = $json;
const status = out.error ? (out.error.code === 'PATH_SECURITY_ERROR' || out.error.code === 'CONFIRMATION_REQUIRED' ? 403 : (out.error.code === 'VALIDATION_ERROR' ? 400 : (out.error.code === 'FILE_SIZE_LIMIT' ? 413 : 500))) : 200;
return { json: { requestId: out.requestId, tool: out.tool, success: out.success, durationMs: out.durationMs, result: out.result, error: out.error, operation: out.operation, _httpStatus: status } };

// Inline JSON schema validation (replaces n8n-nodes-base.validateJson which may not be installed)
const data = $json;
const required = ['requestId', 'tool', 'success', 'durationMs', '_httpStatus'];
const missing = required.filter(k => data[k] === undefined);
if (missing.length > 0) {
  throw new Error(`Schema validation failed — missing fields: ${missing.join(', ')}`);
}
if (typeof data.success !== 'boolean') throw new Error('Schema validation failed — success must be boolean');
if (typeof data.durationMs !== 'number') throw new Error('Schema validation failed — durationMs must be number');
if (typeof data._httpStatus !== 'number') throw new Error('Schema validation failed — _httpStatus must be number');
if (data.error !== null && data.error !== undefined) {
  if (typeof data.error !== 'object') throw new Error('Schema validation failed — error must be object or null');
  if (!data.error.code || !data.error.message) throw new Error('Schema validation failed — error must have code and message');
}
return { json: data };

// Auth Guard — deployed by HomeBot; validates X-HOMEBOT-Auth.
let secret = "";
if (!secret) secret = process.env.HOMEBOT_WEBHOOK_SECRET;
const hdrs = $input.first()?.json?.headers || {};
const incoming = hdrs['x-homebot-auth'] || hdrs['X-HOMEBOT-Auth'] || '';
if (!secret) {
  throw new Error('Unauthorized: this workflow has no HomeBot secret. Deploy it from HomeBot instead of importing it by hand.');
}
if (incoming !== secret) {
  throw new Error('Unauthorized: invalid or missing X-HOMEBOT-Auth header');
}
return $input.all();
